USE `smart_campus_tdtu`;

-- 1. DỮ LIỆU MAP_FEATURES

-- 2. DỮ LIỆU ROAD_NODES

-- 3. DỮ LIỆU ROAD_EDGES

-- 4. RÀNG BUỘC KHÓA NGOẠI: LIÊN KẾT ENTRANCES VỚI ROAD_NODES GẦN NHẤT
UPDATE `place_entrances` pe
JOIN (
    SELECT 
        pe_sub.id AS entrance_id,
        (
            SELECT rn.id 
            FROM `road_nodes` rn 
            ORDER BY ST_Distance_Sphere(rn.geom, pe_sub.geom) ASC 
            LIMIT 1
        ) AS closest_node_id
    FROM `place_entrances` pe_sub
) matched ON pe.id = matched.entrance_id
SET pe.node_id = matched.closest_node_id;
